import React, { useRef } from 'react';

function App() {
  const audioRef = useRef(null);
  const joinDiscord = () => {
    if (audioRef.current) {
      audioRef.current.play().catch(() => {});
    }
    window.open('https://discord.gg/nwcrh7uG9y', '_blank');
  };
  return (
    <>
      <audio ref={audioRef} src="/audio/RobDougan-ClubbedToDeath.mp3" autoPlay loop />
      <div style={{
        minHeight: '100vh',
        background: '#393939',
        color: '#bdbdbd',
        fontFamily: 'Segoe UI, Arial, sans-serif',
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        justifyContent: 'center',
      }}>
        <div style={{
          fontSize: 80,
          fontWeight: 700,
          letterSpacing: 2,
          color: '#888',
          marginBottom: 0,
          textAlign: 'center',
          textTransform: 'uppercase',
        }}>
          CIV 5 MULTIPLAYER
        </div>
        <div style={{
          fontSize: 60,
          fontWeight: 700,
          color: '#bdbdbd',
          letterSpacing: 2,
          marginBottom: 0,
          textAlign: 'center',
          textTransform: 'uppercase',
        }}>
          NO QUIT
        </div>
        <div style={{
          width: 480,
          maxWidth: '90vw',
          height: 16,
          background: 'linear-gradient(90deg, #e74c3c 80%, #888 100%)',
          borderRadius: 8,
          margin: '32px auto 40px auto',
          position: 'relative',
        }}>
          <div style={{
            position: 'absolute',
            right: 0,
            top: -6,
            width: 28,
            height: 28,
            background: '#e74c3c',
            borderRadius: '50%',
            border: '4px solid #393939',
            boxSizing: 'border-box',
          }} />
        </div>
        <div style={{
          background: '#222',
          borderRadius: 8,
          boxShadow: '0 2px 16px #0006',
          padding: '32px 36px',
          margin: '0 auto',
          minWidth: 320,
          maxWidth: '90vw',
          textAlign: 'center',
        }}>
          <button
            onClick={joinDiscord}
            style={{
              background: '#e74c3c',
              color: '#fff',
              border: 'none',
              borderRadius: 4,
              fontFamily: 'inherit',
              fontSize: 22,
              padding: '12px 48px',
              cursor: 'pointer',
              fontWeight: 700,
              marginTop: 8,
              boxShadow: '0 2px 8px #0003',
              transition: 'background 0.2s, color 0.2s',
              outline: 'none',
              textTransform: 'uppercase',
              letterSpacing: 2,
            }}
            onMouseOver={e => {
              e.target.style.background = '#c0392b';
            }}
            onMouseOut={e => {
              e.target.style.background = '#e74c3c';
            }}
          >
            Join Discord
          </button>
        </div>
        <div style={{ color: '#888', fontSize: 15, marginTop: 32, textAlign: 'center' }}>
          <span>Lost your password? Recover it here!</span>
        </div>
      </div>
    </>
  );
}

export default App;
